\begin{figure}[!htbp]
	\centering
	\begin{tikzpicture}[

		node distance=1.5cm and 2cm,

		every node/.style={font=\small, align=center},
		box/.style={draw, rounded corners, minimum width=3.2cm, minimum height=1.3cm, fill=gray!10},
		arrowgreen/.style={-{Latex[length=3mm]}, thick, shorten >=4pt, shorten <=4pt, color=green},
		arrowred/.style={-{Latex[length=3mm]}, thick, shorten >=4pt, shorten <=4pt, color=red},
		arrowblue/.style={-{Latex[length=3mm]}, thick, shorten >=4pt, shorten <=4pt, color=blue},
		arrowgray/.style={-{Latex[length=3mm]}, thick, shorten >=4pt, shorten <=4pt, color=gray},
		desc/.style={midway, fill=white, inner sep=2pt}  
		]
		


		\node[box] (prop31) {Proposition \ref{prop:smooth-decomposition-log-correlated-field}\\(Smooth Decomposition)};
		\node[box, right= of prop31] (lemma46) {Lemma~\ref{lemma:p-moment-higher-derivatives-Xj}\\(Moment Estimates \\of Derivatives)};
		\node[box, below=0.7cm of lemma46] (lemma45) {Lemma \ref{lemma:p-moment-Xj}\\(Moment Estimates)};
		\node[box, right=of lemma46] (prop44) {Proposition \ref{prop:localization}\\(Local Estimate)};
		

		\node[box, below=3cm of prop31] (thm11) {Theorem \ref{thm:Fourier-decay-GMC}\\(Fourier Dimension of GMC)};

		\node[box, below=3 cm of prop44] (prop12) {Proposition \ref{prop:uniform-boundedness-Fourier-Lebesgue-norm}\\($p$-moment of $\mathcal{F}L^{\tau/2,q}$-norm)};
		
		


		\draw[arrowred] (prop31) -- (lemma46);
		\draw[arrowgray] (prop31) -- (lemma45);
		\draw[arrowgray] (lemma45) -- (prop12);
		\draw[arrowred] (lemma46) -- (prop44);
		\draw[arrowred] (prop44) -- (prop12);
		\path (prop44) -- (prop12) node[desc, pos=0.5, right=-2.5cm] {integrate by Pisier's martingale\\ type-$p$ inequality};
		
		\draw[arrowblue] (prop12) -- (thm11);
		\path (prop12) -- (thm11) node[desc, pos=0.5, below=0.3cm] {implies lower bound of $\dim_F(\mu_\infty)$};
		\draw[arrowblue] (prop31) -- (thm11);
		\path (prop31) -- (thm11) node[desc, pos=0.5, right=-1.5cm] {implies upper bound \\of $\dim_F(\mu_\infty)$};
	\end{tikzpicture}
	\caption{Logical flow of the proof of Theorem~\ref{thm:Fourier-decay-GMC}. The color scheme distinguishes the roles of different components in the argument: red highlights the core technical path for establishing the lower bound; blue shows how to obtain the upper and lower bounds for the final theorem; and gray represents supporting derivations.}
	\label{fig:proof_flow}
\end{figure}

